package br.com.luvi.financaspessoais.lancamento.dto; import br.com.luvi.financaspessoais.lancamento.entity.Lancamento; import br.com.luvi.financaspessoais.lancamento.enums.*; import java.math.BigDecimal; import java.time.*; public record LancamentoResponse(Long id,TipoLancamento tipo,String descricao,Categoria categoria,BigDecimal valor,LocalDate data,LocalDateTime dataHoraCadastro,Long contaId,String contaNome,String criadoPor){public static LancamentoResponse from(Lancamento l){return new LancamentoResponse(l.getId(),l.getTipo(),l.getDescricao(),l.getCategoria(),l.getValor(),l.getData(),l.getDataHoraCadastro(),l.getConta()==null?null:l.getConta().getId(),l.getConta()==null?"Conta principal":l.getConta().getNome(),l.getUsuarioCriacao()==null?null:l.getUsuarioCriacao().getNome());}}